#[test]
fn selection_and_copy_state() {
    let mut app = scanned_app("select");
    open_synchronously(&mut app, "src/lib.rs", None);

    let _ = app.update(Message::Editor(EditorMsg::SelectStart {
        pane: 0,
        line: 1,
        col: 4,
    }));
    assert!(app.selecting);
    assert_eq!(app.active_viewer().unwrap().caret, Some((1, 4)));
    let _ = app.update(Message::Editor(EditorMsg::SelectDrag {
        pane: 0,
        line: 3,
        col: 2,
    }));
    let _ = app.update(Message::Editor(EditorMsg::SelectEnd));
    assert!(!app.selecting);

    let v = app.active_viewer().unwrap();
    assert_eq!(v.selection_ordered(), Some(((1, 4), (3, 2))));
    assert_eq!(v.caret, Some((3, 2)));
    let text = v.selected_text().unwrap();
    assert!(text.contains("origin"), "{text}");

    // Esc first answers whatever is layered over the code (opening a .rs file
    // can raise the language-server download prompt) without acting on the
    // code hidden behind it; with nothing on top, Esc clears the selection.
    let esc = || {
        Message::Editor(EditorMsg::KeyPressed(
            keyboard::Key::Named(keyboard::key::Named::Escape),
            keyboard::Modifiers::default(),
        ))
    };
    while crate::ui::escape_message(&app).is_some() {
        let _ = app.update(esc());
        assert!(
            app.active_viewer().unwrap().selection.is_some(),
            "Esc acted on the code behind an overlay"
        );
    }
    let _ = app.update(esc());
    assert!(app.active_viewer().unwrap().selection.is_none());
}

