#[test]
fn consent_gates_project_open() {
    let data = test_dir("consent-data");
    let _ = std::fs::remove_dir_all(&data);
    std::fs::create_dir_all(&data).unwrap();
    // Consent is recorded in clew's data directory, never in the project — a
    // repository must not be able to grant itself permission.
    let _env = data_dir_override(&data);

    let root = fixture_project("consent");

    // Picking an untrusted folder opens the consent modal, not the project.
    let mut app = blank_app();
    let _ = app.update(Message::Project(ProjectMsg::FolderPicked(Some(
        root.clone(),
    ))));
    assert_eq!(app.pending_consent.as_deref(), Some(root.as_path()));
    assert!(app.proj.project.is_none() && !app.scanning);

    // Denied: no project opens, modal dismissed, nothing recorded.
    let _ = app.update(Message::Project(ProjectMsg::ConsentDenied));
    assert!(app.pending_consent.is_none());
    assert!(app.proj.project.is_none() && !app.scanning);
    assert!(app.status.contains("not allowed"), "{}", app.status);
    assert!(!clew_core::trust::Trust::load().is_root_trusted(None, &root));

    // A `.clew/` directory in the project does NOT imply consent: it ships with
    // the repository, so it would let a hostile project trust itself.
    std::fs::create_dir_all(root.join(".clew")).unwrap();
    let mut planted = blank_app();
    let _ = planted.update(Message::Project(ProjectMsg::FolderPicked(Some(
        root.clone(),
    ))));
    assert_eq!(
        planted.pending_consent.as_deref(),
        Some(root.as_path()),
        "a repo-provided .clew must not grant consent"
    );
    assert!(!planted.scanning);

    // Allowed: the scan starts and the trust record is written outside the project.
    let mut app = blank_app();
    let _ = app.update(Message::Project(ProjectMsg::FolderPicked(Some(
        root.clone(),
    ))));
    let _ = app.update(Message::Project(ProjectMsg::ConsentAllowed));
    assert!(app.scanning);
    assert!(app.pending_consent.is_none());
    assert!(clew_core::trust::Trust::load().is_root_trusted(None, &root));

    // A trusted root skips the modal on the next open.
    let mut app2 = blank_app();
    let _ = app2.update(Message::Project(ProjectMsg::FolderPicked(Some(
        root.clone(),
    ))));
    assert!(app2.scanning, "a trusted root must skip the prompt");
    assert!(app2.pending_consent.is_none());
}

#[test]
fn auto_refresh_throttles_but_manual_does_not() {
    use std::time::{Duration, Instant};

    let mut app = blank_app();
    app.llm_available = true;
    app.llm_config_cache = Some(Some(unreachable_llm()));

    // Nothing explained yet → auto-refresh is a no-op (first build is manual).
    let _ = app.request_auto_refresh();
    assert!(app.proj.last_auto_refresh.is_none() && !app.proj.refresh_pending);

    // Seed one explanation so there's something to keep fresh.
    app.proj.explain.cache.insert(
        explain::Node::File(PathBuf::from("a.rs")),
        explain::Cached {
            summary: "s".into(),
            prompt_hash: 1,
            detail: None,
            basis: None,
        },
    );

    // First change fires immediately (no prior refresh): stamps the cooldown.
    let _ = app.request_auto_refresh();
    let first = app.proj.last_auto_refresh.expect("cooldown stamped");
    assert!(!app.proj.refresh_pending, "a fresh pass isn't 'pending'");

    // A second change inside the 30s window is deferred, not fired: the stamp
    // is unchanged and the pass is now pending.
    let _ = app.request_auto_refresh();
    assert_eq!(
        app.proj.last_auto_refresh,
        Some(first),
        "cooldown not restamped"
    );
    assert!(app.proj.refresh_pending, "change during cooldown is queued");

    // Once the window has passed, the queued change fires and restamps.
    app.proj.last_auto_refresh = Some(Instant::now() - Duration::from_secs(31));
    let _ = app.request_auto_refresh();
    assert!(
        app.proj.last_auto_refresh.unwrap() > first,
        "restamped after cooldown"
    );
    assert!(!app.proj.refresh_pending, "queued pass consumed");

    // A manual refresh ignores the cooldown entirely. A second into the
    // window an automatic request still only queues — nothing runs…
    let stamped = Instant::now() - Duration::from_secs(1);
    app.proj.last_auto_refresh = Some(stamped);
    assert!(
        run_task(app.request_auto_refresh()).is_empty(),
        "an automatic refresh inside the window must not start a pass"
    );
    assert!(app.proj.refresh_pending);
    // …while the manual one starts the pass now and restamps the window.
    let started = run_task(app.update(Message::Explain(ExplainMsg::RefreshAll)));
    assert!(
        started
            .iter()
            .any(|m| matches!(m, Message::Explain(ExplainMsg::Project))),
        "a manual refresh inside the window must start an explicit pass: {started:?}"
    );
    assert!(
        app.proj.last_auto_refresh.unwrap() > stamped,
        "the manual pass restamps the cooldown"
    );
    assert!(!app.proj.refresh_pending, "the queued change rides along");
}

#[test]
fn search_flow_message_wiring() {
    let mut app = scanned_app("search");

    let (root, files) = {
        let project = app.proj.project.as_ref().unwrap();
        (project.root.clone(), project.files.clone())
    };
    let result = search::search_in(
        &root,
        files,
        search::SearchOptions {
            query: "needle".to_string(),
            ..Default::default()
        },
    );
    assert_eq!(result.hits.len(), 1);
    let _ = app.update(Message::Nav(NavMsg::SearchDone {
        stamp: app.stamp(),
        seq: app.proj.search_seq,
        result: search::SearchReport {
            hits: result.hits,
            error: result.error,
            skipped: Vec::new(),
        },
    }));
    assert_eq!(app.proj.search.hits.len(), 1);
    assert_eq!(app.proj.search.hits[0].rel, "notes.txt");

    // Clicking a hit opens the file at that line.
    let hit = app.proj.search.hits[0].clone();
    let _ = app.update(Message::Editor(EditorMsg::OpenAbs {
        abs: hit.abs.clone(),
        line: Some(hit.line),
        push: true,
    }));
    let content = read_text_file(&hit.abs).unwrap();
    let req = app.proj.link.pane_pending[0].expect("open_file minted a load token");
    let _ = app.update(Message::Editor(EditorMsg::FileLoaded {
        stamp: app.stamp(),
        req,
        pane: 0,
        abs: hit.abs,
        target: Some(hit.line),
        result: Ok(content),
    }));
    assert_eq!(app.active_viewer().unwrap().target_line, Some(1));
}

