/// Right-click opens a navigation menu carrying the clicked position;
/// choosing an action closes it.
#[test]
fn context_menu_flow() {
    let mut app = scanned_app("ctxmenu");
    open_synchronously(&mut app, "src/lib.rs", None);

    let _ = app.update(Message::Hover(HoverMsg::ContextMenuOpened {
        pane: 0,
        line: 2,
        col: 7,
        x: 120.0,
        y: 40.0,
    }));
    let menu = app.proj.context_menu.expect("menu open");
    assert_eq!((menu.line, menu.col), (2, 7));

    // Choosing an action closes the menu and dispatches the goto for the
    // menu's pane: pane 0 holds Rust, whose server is not running here, so
    // the goto says so (a goto that never ran would leave the status alone).
    app.status.clear();
    let _ = app.update(Message::Hover(HoverMsg::ContextGoto(GotoKind::Definition)));
    assert!(app.proj.context_menu.is_none());
    assert!(
        app.status.contains("No rust server ready"),
        "the goto was not dispatched: {:?}",
        app.status
    );

    // Outside click / Esc closes without acting: a goto chosen after that
    // has no menu to act for.
    let _ = app.update(Message::Hover(HoverMsg::ContextMenuOpened {
        pane: 0,
        line: 0,
        col: 0,
        x: 0.0,
        y: 0.0,
    }));
    let _ = app.update(Message::Hover(HoverMsg::ContextMenuClosed));
    assert!(app.proj.context_menu.is_none());
    app.status.clear();
    let _ = app.update(Message::Hover(HoverMsg::ContextGoto(GotoKind::Definition)));
    assert_eq!(app.status, "", "a closed menu dispatched a goto");
}

