/// The variant name of a message (its `Debug` form up to the payload).
/// The feature and variant of a message, `Feature::Variant`, from its `Debug`
/// form (`Feature(Variant …)`).
fn variant_name(msg: &Message) -> String {
    let debug = format!("{msg:?}");
    let mut parts = debug.split([' ', '(', '{', ')']).filter(|p| !p.is_empty());
    let feature = parts.next().unwrap_or_default();
    match parts.next() {
        Some(variant) => format!("{feature}::{variant}"),
        None => feature.to_string(),
    }
}

/// W2-S S2: every async-result message carries a `Stamp`, and one that no
/// longer belongs here — another project instance, another root, or (for
/// transport-bound work) a transport since replaced — is dropped by the ONE
/// check at the top of `dispatch`, before any handler: the per-arm guards it
/// replaced are gone. The drop counter proves it is this check that drops
/// each sample, whether or not its handler would have dropped it as well —
/// a few would: the time-travel `Ready`, say, answers a start this test
/// never made, and its handler applies only the one start awaited. The
/// samples cover every variant the source declares with a `stamp` field
/// (bar the one whose handler decides, see `DebugMsg::AdapterInstalled`), so
/// a new stamped variant cannot be left out of this proof.
#[test]
fn a_stale_stamp_on_every_stamped_message_is_dropped_by_the_one_check() {
    let mut app = scanned_app("stale-stamps");
    let current = app.transport_stamp();
    // Every variant declared with a stamp is sampled.
    let source = include_str!("message.rs");
    let mut declared = std::collections::BTreeSet::new();
    let (mut feature, mut variant) = (None, None);
    for line in source.lines() {
        if let Some(name) = line
            .strip_prefix("pub enum ")
            .and_then(|l| l.strip_suffix("Msg {"))
        {
            feature = Some(name.to_string());
        }
        if let Some(name) = line
            .strip_prefix("    ")
            .and_then(|l| l.strip_suffix(" {"))
            .filter(|n| n.chars().next().is_some_and(|c| c.is_ascii_uppercase()))
            .filter(|n| n.chars().all(char::is_alphanumeric))
        {
            variant = feature.as_ref().map(|f| format!("{f}::{name}"));
        }
        if line.trim() == "stamp: Stamp," {
            declared.extend(variant.clone());
        }
    }
    declared.remove("Debug::AdapterInstalled");
    assert!(declared.len() > 50, "the stamped variants were not found");
    let sampled: std::collections::BTreeSet<String> = stamped_samples(&app, &current)
        .iter()
        .map(variant_name)
        .collect();
    assert_eq!(sampled, declared, "the samples miss a stamped variant");

    let stale = [
        Stamp {
            epoch: current.epoch + 1,
            ..current.clone()
        },
        Stamp {
            root: Some(PathBuf::from("/another/project")),
            ..current.clone()
        },
        Stamp {
            conn: Some(app.conn_gen + 1),
            ..current.clone()
        },
    ];
    for stamp in &stale {
        for msg in stamped_samples(&app, stamp) {
            let name = variant_name(&msg);
            assert!(
                matches!(msg.origin(), Some(Origin::Stamped(s)) if s == stamp),
                "{name} is not checked by its stamp"
            );
            let (dropped, status) = (app.stale_dropped, app.status.clone());
            let _ = app.update(msg);
            assert_eq!(
                app.stale_dropped,
                dropped + 1,
                "{name} with a stale stamp was not dropped by the one check"
            );
            assert_eq!(app.status, status, "{name} reached its handler");
        }
    }
    // The project and the transport are untouched by all of it.
    assert!(app.proj.project.is_some() && app.debug.session.is_none());

    // A current stamp passes the same check (its handler decides the rest).
    for msg in stamped_samples(&app, &app.transport_stamp()) {
        let (name, dropped) = (variant_name(&msg), app.stale_dropped);
        let _ = app.update(msg);
        assert_eq!(
            app.stale_dropped, dropped,
            "{name} was dropped while current"
        );
    }
}

/// W2-S S2: transport events answer to the transport instance, through the
/// same check: a late event from a transport the window has since replaced
/// is dropped before its handler; the live transport's is not.
#[test]
fn a_transport_event_from_a_replaced_transport_takes_the_same_check() {
    let mut app = blank_app();
    let _rx = attach_server(&mut app);
    let stale = app.conn_gen;
    app.conn_gen += 1;
    let (tx, _rx2) = tokio::sync::mpsc::channel(crate::server::REQUEST_QUEUE);
    for msg in [
        Message::Server(ServerMsg::Connected { conn: stale, tx }),
        Message::Server(ServerMsg::Disconnected {
            conn: stale,
            reason: None,
        }),
        Message::Server(ServerMsg::Unavailable {
            conn: stale,
            reason: "stale".into(),
        }),
        Message::Server(ServerMsg::Event {
            conn: stale,
            msg: clew_protocol::ServerMessage::Notification {
                event: clew_protocol::Event::Status {
                    message: "stale".into(),
                },
            },
        }),
    ] {
        let name = variant_name(&msg);
        assert!(matches!(msg.origin(), Some(Origin::Transport(c)) if c == stale));
        let (dropped, status) = (app.stale_dropped, app.status.clone());
        let _ = app.update(msg);
        assert_eq!(app.stale_dropped, dropped + 1, "{name} was not dropped");
        assert_eq!(app.status, status, "{name} reached its handler");
    }
    assert!(
        app.server.is_up(),
        "a stale event tore down the live transport"
    );
    // The live transport's own events are admitted.
    let conn = app.conn_gen;
    let dropped = app.stale_dropped;
    let _ = app.update(Message::Server(ServerMsg::Disconnected {
        conn,
        reason: None,
    }));
    assert_eq!(app.stale_dropped, dropped);
    assert!(!app.server.is_up());
}

